scwin.dragStart = function (rowIndex, rowXml, info) {
    debugger;
    scwin.dragRow = rowIndex;
    return rowXml; // 드래그한 row에 담긴 데이터를 dragEndFunction(여기서는 dragEnd함수)의 두번째 인자로 사용

}

scwin.dragEnd = function (targetRowIndex, rowXml, info) {
    debugger;
    dataList1.removeRow(scwin.dragRow); // 드래그한 Row 삭제
    dataList1.setRowXML(targetRowIndex, rowXml); // 드랍한 Row에 rowXml값을 set
    return false; // true인 경우만 처음 dragdrop이 시작됐던 rowIndex에 해당하는 row를 삭제한다.
}
